pub const fn rumble_p1(ctx: &Ctx) -> f32 {
    50f32
        + 0.25 * ctx.ability_power
        + 80f32 * (-1f32 + ctx.level) * (0.7025 + 0.0175 * (-1f32 + ctx.level))
            / 17f32
}

pub const fn rumble_p2(ctx: &Ctx) -> f32 {
    0.04 * ctx.enemy_max_health
}

pub const fn rumble_p3(ctx: &Ctx) -> f32 {
    ctx.attack_speed * (0.5 + 0.0339 * (-1f32 + ctx.level))
}

pub const fn rumble_p4(ctx: &Ctx) -> f32 {
    5f32 + 2.06 * (-1f32 + ctx.level)
}

pub const fn rumble_p5(ctx: &Ctx) -> f32 {
    match ctx.level as u8 {
        ..2 => 65f32,
        2 => 68.6,
        3 => 72.38,
        4 => 76.33,
        5 => 80.45,
        6 => 84.75,
        7 => 89.23,
        8 => 93.88,
        9 => 98.7,
        10 => 103.7,
        11 => 108.88,
        12 => 114.23,
        13 => 119.75,
        14 => 125.45,
        15 => 131.32,
        16 => 137.38,
        17 => 143.6,
        18 => 150f32,
        19 => 156.57,
        20.. => 163.32,
    }
}

